INSERT INTO comments (id, thread, parent_id, handle, role_tag, market, body, votes, flags, status, ip_hash, created_at)
VALUES ('pin-green-room', 'green-room', NULL, 'Fat City', 'operator', NULL, 'What do you get paid per game — and what''s actually included?' || char(10) || '' || char(10) || 'Rates for this work are all over the map and nobody can find out what anything is worth without asking a stranger. So: what''s your number, what''s the format, how long is the game, and does the venue cover your tab?' || char(10) || '' || char(10) || 'We''ll go first. These are Fat City''s real numbers — Canadian dollars, weekday show, roughly three hours on site.' || char(10) || '' || char(10) || 'A one-off weekday show is $450. Almost nobody pays that, and it isn''t a bluff price — a single night is genuinely the most expensive way to buy this. Nothing amortises. We price it to reflect that.' || char(10) || '' || char(10) || 'Booked as a recurring night it''s $225. Three or four dates is the minimum that makes sense; twelve booked at once is what we''re actually aiming for. There''s one step past that: $200 flat if the venue puts a $25 tab behind the bar for the host. We''d rather give the tab than the $25, and further down this thread we''ll explain why that trade is better for the venue than it looks.' || char(10) || '' || char(10) || 'Weekends, holidays and special events are full rate or higher. A two-host Christmas party starts at $900.' || char(10) || '' || char(10) || 'The part that catches new hosts out is the cost side. Budget about $50 a night for licensing games, printing cards and consumables. So on a $225 night you keep $175 for about three hours. On the $200-plus-tab deal you keep $150 and drink for free. Work out your costs before you agree to a number, not after.' || char(10) || '' || char(10) || 'That''s ours. What''s yours?', 0, 0, 'pinned', NULL, strftime('%s','now')*1000)
ON CONFLICT(id) DO UPDATE SET body = excluded.body, handle = excluded.handle,
